import{_ as o,o as r,c as n,a2 as s}from"./chunks/framework.DGvnA5EY.js";const a="/workbuddy-guide/assets/01-official-connector-list.1yj5GbzF.png",e="/workbuddy-guide/assets/06-connector-as-gate.D0yESgeK.png",d="/workbuddy-guide/assets/05-official-enable-in-task.aVAh6S_5.png",l="/workbuddy-guide/assets/02-official-qq-qrcode.CpvZGV-q.png",g="/workbuddy-guide/assets/03-official-qq-permission.DqVZH-62.png",i="/workbuddy-guide/assets/04-official-connected.BaJxHxs7.png",P=JSON.parse('{"title":"第 7 章 使用连接器","description":"> 内容来源：WorkBuddy 官方指南 · 连接器（非官方整理，© 本指南作者，保留所有权利） 前两章你有了工具（Skill）和专业身份（专家）。但还有一个问题没解决： AI 怎么碰到你公司邮箱里的那封邮件？ 连接器就是干这个的—— 把外部服务接进来，让 AI 能在你授权的范围内读取和操作外部数据。","frontmatter":{"title":"第 7 章 使用连接器"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 7 章 使用连接器/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 7 章 使用连接器/index.md","lastUpdated":1791615980000}'),h={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 7 章 使用连接器/index.md"};function p(u,t,c,b,q,k){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="第-7-章-使用连接器" tabindex="-1">第 7 章 使用连接器 <a class="header-anchor" href="#第-7-章-使用连接器" aria-label="Permalink to &quot;第 7 章 使用连接器&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 · 连接器（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>前两章你有了工具（Skill）和专业身份（专家）。但还有一个问题没解决： <strong>AI 怎么碰到你公司邮箱里的那封邮件？</strong> 连接器就是干这个的—— 把外部服务接进来，让 AI 能在你授权的范围内读取和操作外部数据。</p><h2 id="一、连接器是什么" tabindex="-1">一、连接器是什么 <a class="header-anchor" href="#一、连接器是什么" aria-label="Permalink to &quot;一、连接器是什么&quot;">​</a></h2><p>连接器用于<strong>将 WorkBuddy 与外部服务对接</strong>，把外部数据和能力引入 AI 工作流。 配置好之后，WorkBuddy 在获得授权后就能访问和操作第三方服务。</p><p>从实现形态看分两种：<strong>MCP + CLI</strong>（标准化协议）和 <strong>Skill + CLI</strong>（内置脚本）， 两者在数据收集和权限边界上遵循一致原则。</p><p><strong>当前已支持</strong>：QQ 邮箱、腾讯文档、腾讯乐享、腾讯会议、TAPD、腾讯网盘等， 同时支持自定义连接器。</p><p><img src="'+a+'" alt="连接器管理页面：QQ邮箱、腾讯文档、腾讯会议、企业微信、飞书、钉钉、TAPD 等卡片，每张右上角有 + 号" loading="lazy"></p><p><em>此图片来自官方。</em></p><h2 id="二、连接器能做什么" tabindex="-1">二、连接器能做什么 <a class="header-anchor" href="#二、连接器能做什么" aria-label="Permalink to &quot;二、连接器能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>数据查询</strong></td><td>从外部数据源获取信息</td><td>查询数据库、检索文档</td></tr><tr><td><strong>服务调用</strong></td><td>调用第三方 API 完成操作</td><td>发送邮件、创建日程</td></tr><tr><td><strong>文件管理</strong></td><td>访问云端存储与文件系统</td><td>读取网盘文件、上传附件</td></tr><tr><td><strong>消息通知</strong></td><td>与即时通讯工具集成</td><td>发送企业微信/飞书消息</td></tr></tbody></table><p><strong>一句话理解</strong>：连接器是<strong>AI 通向外面的门</strong>。没连接器，AI 只能处理你喂给它的东西； 连上之后，它能自己去取。</p><p><img src="'+e+'" alt="左边门关着只能投喂，右边授权开门后 AI 自己把外面的数据取回" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解连接器的作用，与实际软件界面无关。</em></p><h2 id="三、添加连接器-4-步" tabindex="-1">三、添加连接器：4 步 <a class="header-anchor" href="#三、添加连接器-4-步" aria-label="Permalink to &quot;三、添加连接器：4 步&quot;">​</a></h2><ol><li>在左侧边栏点击**「专家·技能·连接器」<strong>，选中</strong>连接器**页签</li><li>找到需要使用的连接器，点击卡片右上方的 <strong><code>+</code></strong></li><li>按页面提示完成<strong>登录、授权</strong>或其他配置</li><li>完成授权后，即可在 WorkBuddy 中使用该连接器</li></ol><h2 id="四、使用连接器-三种方式" tabindex="-1">四、使用连接器：三种方式 <a class="header-anchor" href="#四、使用连接器-三种方式" aria-label="Permalink to &quot;四、使用连接器：三种方式&quot;">​</a></h2><p>连接器支持多种用法，你可以提前授权，也可以在任务中按需添加。</p><h3 id="方式一-从连接器页面直接发起对话" tabindex="-1">方式一：从连接器页面直接发起对话 <a class="header-anchor" href="#方式一-从连接器页面直接发起对话" aria-label="Permalink to &quot;方式一：从连接器页面直接发起对话&quot;">​</a></h3><p>在<strong>连接器管理</strong>页面中，找到已授权的连接器，点击卡片右上角的**「去对话」**， 直接开始使用。<strong>适合你已经知道要用哪个连接器的时候。</strong></p><h3 id="方式二-创建任务时启用" tabindex="-1">方式二：创建任务时启用 <a class="header-anchor" href="#方式二-创建任务时启用" aria-label="Permalink to &quot;方式二：创建任务时启用&quot;">​</a></h3><p>新建任务时，点击输入框左下角的 <strong><code>+</code> &gt; 连接器</strong>，在弹窗中开启需要的连接器。</p><p><img src="'+d+'" alt="输入框左下角的 + 号，展开后可以选择连接器" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>尚未完成授权的连接器，需要先完成授权后才能使用。</strong></p><h3 id="方式三-执行任务时按需连接-最省心" tabindex="-1">方式三：执行任务时按需连接（最省心） <a class="header-anchor" href="#方式三-执行任务时按需连接-最省心" aria-label="Permalink to &quot;方式三：执行任务时按需连接（最省心）&quot;">​</a></h3><p>任务执行过程中，如果需要用到尚未连接的连接器，<strong>输入框上方会自动显示 连接引导卡片</strong>。点卡片并按提示完成授权后，WorkBuddy 将<strong>自动继续执行当前任务</strong>， <strong>无需重新发起对话</strong>。</p><p><strong>这个设计对你很友好</strong>：不用提前把所有连接器都授权一遍，用到哪个说哪个。</p><h2 id="五、停止使用与解绑" tabindex="-1">五、停止使用与解绑 <a class="header-anchor" href="#五、停止使用与解绑" aria-label="Permalink to &quot;五、停止使用与解绑&quot;">​</a></h2><p>这两件事要分清：</p><table tabindex="0"><thead><tr><th>操作</th><th>怎么做</th><th>效果</th></tr></thead><tbody><tr><td><strong>停止使用</strong></td><td>输入框左下角 <strong><code>+</code> &gt; 连接器</strong>，取消对应连接器的启用状态</td><td>暂时不用，但<strong>授权还在</strong></td></tr><tr><td><strong>解绑</strong></td><td>连接器管理页面 → 选中已连接的连接器 → 弹窗中点**「解绑」**</td><td><strong>断开授权</strong>，恢复为未连接状态</td></tr></tbody></table><p><strong>什么时候该解绑</strong>：不再用的连接器<strong>建议及时撤销授权</strong>—— 授权 Token 相当于你账号的钥匙，闲着不用就收起来。</p><h2 id="六、实战-连接-qq-邮箱-最常用的一个" tabindex="-1">六、实战：连接 QQ 邮箱（最常用的一个） <a class="header-anchor" href="#六、实战-连接-qq-邮箱-最常用的一个" aria-label="Permalink to &quot;六、实战：连接 QQ 邮箱（最常用的一个）&quot;">​</a></h2><p>QQ 邮箱连接器支持<strong>收发、搜索和整理</strong> QQ 邮件：用自然语言读取邮件内容、 汇总邮件线程、管理文件夹。</p><h3 id="第-1-步-发起连接" tabindex="-1">第 1 步：发起连接 <a class="header-anchor" href="#第-1-步-发起连接" aria-label="Permalink to &quot;第 1 步：发起连接&quot;">​</a></h3><p>在连接器管理页面找到<strong>QQ 邮箱</strong>卡片，点击右侧的 <strong><code>+</code></strong> 按钮。</p><h3 id="第-2-步-扫码授权" tabindex="-1">第 2 步：扫码授权 <a class="header-anchor" href="#第-2-步-扫码授权" aria-label="Permalink to &quot;第 2 步：扫码授权&quot;">​</a></h3><p>系统跳转到 QQ 邮箱授权页面，显示二维码。 用 <strong>QQ 邮箱 App</strong>（7.1.5 / 鸿蒙 0.2.9 及更新版本）扫码授权。</p><p><img src="'+l+'" alt="QQ 邮箱授权页：显示二维码，提示用 QQ 邮箱 App 扫码授权" loading="lazy"></p><p><em>此图片来自官方。</em></p><h3 id="第-3-步-确认权限-这一步最重要" tabindex="-1">第 3 步：确认权限（这一步最重要） <a class="header-anchor" href="#第-3-步-确认权限-这一步最重要" aria-label="Permalink to &quot;第 3 步：确认权限（这一步最重要）&quot;">​</a></h3><p>在手机端确认 WorkBuddy 申请的访问权限：</p><p><img src="'+g+'" alt="手机端授权页：账号信息、读取邮件、发送邮件三个开关默认开启，删除邮件默认关闭" loading="lazy"></p><p><em>此图片来自官方。</em></p><table tabindex="0"><thead><tr><th>权限</th><th>内容</th><th>建议</th></tr></thead><tbody><tr><td><strong>账号信息</strong></td><td>获取邮箱账号基础信息</td><td>必需</td></tr><tr><td><strong>读取邮件</strong></td><td>读取收件箱内<strong>近一个月</strong>的邮件</td><td>必需</td></tr><tr><td><strong>发送邮件</strong></td><td>代为发送邮件</td><td>常用就开</td></tr><tr><td><strong>删除邮件</strong>（可选）</td><td>已删除邮件会移入「已删除」文件夹</td><td><strong>默认关闭，建议别开</strong></td></tr></tbody></table><p>确认无误后点**「同意授权」**。</p><p><strong>为什么建议关掉&quot;删除邮件&quot;？</strong> 删邮件是不可逆操作，AI 误删你一封重要邮件 你找不回来。<strong>读和发都够用了，删除这个权限没必要给。</strong></p><h3 id="第-4-步-完成连接" tabindex="-1">第 4 步：完成连接 <a class="header-anchor" href="#第-4-步-完成连接" aria-label="Permalink to &quot;第 4 步：完成连接&quot;">​</a></h3><p>授权成功时点击浏览器弹窗中的**「打开」**完成连接。</p><blockquote><p><strong>提示</strong>：取消或者直接关闭网页<strong>可能会导致操作中断</strong>，需要重新配置连接器。</p></blockquote><p>授权成功后，可在「设置 - 账号 - 安全管理 - 登录设备和授权码 - 应用授权」 中管理授权应用。</p><h3 id="第-5-步-确认连接成功" tabindex="-1">第 5 步：确认连接成功 <a class="header-anchor" href="#第-5-步-确认连接成功" aria-label="Permalink to &quot;第 5 步：确认连接成功&quot;">​</a></h3><p>回到 WorkBuddy，QQ 邮箱卡片名称旁会出现<strong>绿色圆点</strong>，并提示 <strong>「连接器 QQ 邮箱 已连接」</strong>，右侧显示「去对话」按钮。</p><p><img src="'+i+'" alt="连接完成：QQ 邮箱卡片名称旁出现绿色圆点，右侧显示去对话按钮" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>看到绿点就成了。</strong></p><h2 id="七、实战-连接腾讯乐享" tabindex="-1">七、实战：连接腾讯乐享 <a class="header-anchor" href="#七、实战-连接腾讯乐享" aria-label="Permalink to &quot;七、实战：连接腾讯乐享&quot;">​</a></h2><p>腾讯乐享连接器支持<strong>搜索、创建和管理</strong>乐享知识库中的文档， 支持导入 Markdown、按标签整理内容、追踪团队文档的更新动态。</p><p>流程和 QQ 邮箱类似：</p><ol><li><p>在连接器管理页面找到<strong>腾讯乐享</strong>卡片，点击 <strong><code>+</code></strong></p></li><li><p>进入授权确认页面，通过乐享知识库 MCP，WorkBuddy 将能够：</p><ul><li>按你拥有的权限访问知识库</li><li>搜索、查询知识库中的内容</li><li>协助创建与管理知识库中的内容</li></ul><p>确认无误后点**「立即前往授权」**</p></li><li><p>登录乐享知识库，支持<strong>微信登录</strong>、<strong>手机号登录</strong>两种方式</p></li><li><p>页面显示账号信息及 WorkBuddy 将要获取的权限，确认后点**「继续」**</p></li><li><p>回到 WorkBuddy，卡片旁出现<strong>绿色圆点</strong>，右侧显示「去对话」按钮</p></li></ol><h2 id="八、自定义连接器" tabindex="-1">八、自定义连接器 <a class="header-anchor" href="#八、自定义连接器" aria-label="Permalink to &quot;八、自定义连接器&quot;">​</a></h2><p>如需接入其他外部服务，点连接器管理页面右上角的**「自定义连接器」**按钮， 安装自定义的 MCP 服务。</p><blockquote><p><strong>提示</strong>：自定义连接器的配置方式与 MCP 配置类似。</p></blockquote><p><strong>注意</strong>：自定义连接器的访问范围<strong>由你的配置决定</strong>，官方不预设范围， <strong>请审慎评估后再启用</strong>。</p><h2 id="九、安全边界-官方明确的四条" tabindex="-1">九、安全边界：官方明确的四条 <a class="header-anchor" href="#九、安全边界-官方明确的四条" aria-label="Permalink to &quot;九、安全边界：官方明确的四条&quot;">​</a></h2><h3 id="权限边界三条" tabindex="-1">权限边界三条 <a class="header-anchor" href="#权限边界三条" aria-label="Permalink to &quot;权限边界三条&quot;">​</a></h3><ul><li><strong>每个连接器独立授权</strong> —— 连了 QQ 邮箱不代表连了腾讯文档</li><li><strong>不主动定时抓取</strong> —— 它只在你下指令时才去取数据</li><li><strong>不超出你已有权限范围</strong> —— 你在 QQ 邮箱里本来就读不到的，它也读不到</li></ul><h3 id="会收集哪些信息" tabindex="-1">会收集哪些信息 <a class="header-anchor" href="#会收集哪些信息" aria-label="Permalink to &quot;会收集哪些信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>收集项</th><th>类型</th><th>用途</th></tr></thead><tbody><tr><td>第三方账号标识</td><td>必要</td><td>邮箱地址、账号 ID 等，用于识别身份</td></tr><tr><td>授权凭据</td><td>必要</td><td>OAuth Access/Refresh Token，或你手动填写的 API 密钥</td></tr><tr><td>第三方业务数据</td><td>必要</td><td><strong>仅在你的指令触发时</strong>按需读取（邮件、文档、知识库、会议、TAPD 项目数据等）</td></tr><tr><td>用户写入数据</td><td>非必要</td><td>代发邮件、创建/编辑文档、创建会议等，<strong>需你明确指令确认</strong></td></tr></tbody></table><h3 id="两个提醒" tabindex="-1">两个提醒 <a class="header-anchor" href="#两个提醒" aria-label="Permalink to &quot;两个提醒&quot;">​</a></h3><ul><li><strong>积分消耗</strong>：连接器自身的读写<strong>不消耗积分</strong>；但 WorkBuddy 对<strong>外部数据</strong> 进行理解、汇总时<strong>会消耗积分</strong>。</li><li><strong>第三方共享</strong>：<strong>用连接器就等于跟第三方服务交互</strong>，凭据由 WorkBuddy 维护 以便代你调用。</li></ul><h3 id="使用建议-官方原文要点" tabindex="-1">使用建议（官方原文要点） <a class="header-anchor" href="#使用建议-官方原文要点" aria-label="Permalink to &quot;使用建议（官方原文要点）&quot;">​</a></h3><ul><li>连接器调用产生的访问、读写、消息发送，<strong>均以你本人身份执行</strong>， <strong>建议在涉及对外发送、内容修改前再次确认目标对象与内容</strong></li><li>API 密钥与 Token 是访问你第三方账号的钥匙，<strong>请妥善保管，避免在公共设备 或共享环境填写</strong></li><li>不再使用的连接器<strong>建议及时撤销授权</strong></li></ul><h2 id="十、本章动手-连一个你真的会用到的" tabindex="-1">十、本章动手：连一个你真的会用到的 <a class="header-anchor" href="#十、本章动手-连一个你真的会用到的" aria-label="Permalink to &quot;十、本章动手：连一个你真的会用到的&quot;">​</a></h2><ol><li>进**「专家·技能·连接器」→ 连接器**</li><li>找<strong>QQ 邮箱</strong>，点 <code>+</code>，按提示扫码</li><li>在手机端确认权限，<strong>把&quot;删除邮件&quot;保持关闭</strong></li><li>授权完成后点浏览器弹窗的**「打开」**</li><li>回到页面确认出现<strong>绿点 + 「去对话」</strong></li><li>点**「去对话」**，试一次：&quot;帮我看看最近一周有哪些重要邮件没回&quot;</li></ol><h2 id="十一、本章任务清单-做完就算过关" tabindex="-1">十一、本章任务清单（做完就算过关） <a class="header-anchor" href="#十一、本章任务清单-做完就算过关" aria-label="Permalink to &quot;十一、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 说出连接器的作用（把外部服务接进来，AI 能自己取数据）</li><li>[ ] 知道已支持哪些（QQ邮箱、腾讯文档、乐享、会议、TAPD、网盘…）</li><li>[ ] 说出连接器能做的 4 类事（查询、调用、文件、消息）</li><li>[ ] 独立完成一次 QQ 邮箱授权，页面出现绿点和「去对话」</li><li>[ ] 知道&quot;停止使用&quot;和&quot;解绑&quot;的区别</li><li>[ ] 授权时看清楚每项权限，<strong>没必要的权限不开</strong>（尤其删除类）</li><li>[ ] 知道&quot;取消授权网页会中断连接&quot;这个坑</li><li>[ ] 知道 Token 不能在公共设备上填</li><li>[ ] 不用了的连接器会及时撤销授权</li></ul><hr><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p>这一章是术语最密集的一章，慢慢看。</p></blockquote><p><strong>连接器（Connector）</strong> 把外部服务接到 WorkBuddy 上的一道<strong>门</strong>。接上之后 AI 能自己进去取东西， 不用你手动复制粘贴。类比：Skill 是给 AI 加工具，连接器是给 AI 开门。</p><p><strong>外部服务</strong> 指 WorkBuddy 之外的东西：你的 QQ 邮箱、腾讯文档、企业微信、TAPD 项目…… 这些数据本来在别人的服务器上，AI 碰不到。</p><p><strong>授权 / 扫码授权</strong> 让第三方服务同意&quot;WorkBuddy 可以代表我访问我的数据&quot;。 你扫一次码、在手机上点&quot;同意&quot;，就等于把自己的钥匙交给了它。 <strong>授权是可撤销的。</strong></p><p><strong>OAuth Token</strong> 授权成功后拿到的一串&quot;钥匙&quot;。有了它 AI 才能代表你访问， <strong>不用每次输密码</strong>。这串东西很敏感，泄露了等于别人能登你账号。</p><p><strong>API 密钥</strong> 有些服务用一串字符当钥匙代替扫码。作用和 Token 一样， <strong>同样要当密码保管。</strong></p><p><strong>数据查询 / 服务调用 / 文件管理 / 消息通知</strong> 连接器能干的四类活：</p><ul><li><strong>查询</strong>：去数据库或文档里找信息</li><li><strong>调用</strong>：调第三方接口做事（发邮件、建日程）</li><li><strong>文件</strong>：读网盘、传附件</li><li><strong>消息</strong>：往企微/飞书发通知</li></ul><p><strong>绿色圆点</strong> 连接成功的标志。看到它就说明授权已完成、连接器可以用了。 <strong>如果授权了还是没绿点</strong>，多半是网页被关掉了，需要重新配。</p><p><strong>「去对话」</strong> 直接用这个连接器开一个对话。适合你已经明确要用哪个服务的时候。</p><p><strong>按需连接 / 连接引导卡片</strong> 任务执行中才弹出授权提示。用到哪个才问哪个， 不用提前把一堆连接器全授权。授权后<strong>任务会自动继续</strong>，不用重新发起。</p><p><strong>解绑</strong> 断开连接、撤销授权。解绑后连接器恢复未连接状态。 <strong>不用了记得解绑</strong>，别让钥匙一直挂在那。</p><p><strong>停止使用</strong> 临时关闭，<strong>授权还保留着</strong>。和解绑的区别就在这。</p><p><strong>自定义连接器</strong> 官方没提供的服务，你可以自己装一个 MCP 服务来接。 <strong>访问范围完全由你的配置决定</strong>，官方不预设，所以要自己评估风险。</p><p><strong>MCP</strong> 一个让外部工具接入 AI 的标准协议。官方连接器里两种实现方式之一就是 &quot;MCP + CLI&quot;。你只要知道&quot;它是接外部工具的协议&quot;就行。</p><p><strong>权限边界三条</strong></p><ul><li><strong>独立授权</strong>：连一个不等于连全部</li><li><strong>不主动抓取</strong>：不下指令就不去取</li><li><strong>不超出已有权限</strong>：你读不到的，它也读不到</li></ul><p>这三条是官方给的边界承诺，说明它不会偷偷多拿你的数据。</p><p><strong>删除邮件这个权限</strong> 危险权限之一。AI 删邮件<strong>不可逆</strong>。默认是关闭的， <strong>建议就让它关着</strong>——读和发够用了。</p><p><strong>Token / 密钥泄露的后果</strong> 拿到 Token 的人<strong>可以以你的身份</strong>访问邮箱、文档等。 所以<strong>别在网吧、别人电脑上填</strong>。用完的连接器及时撤销。</p><hr><p><em>下一篇：第 8 章 接入小程序与 IM 助理——让 AI 在手机上也能干活。</em></p>',101)])])}const f=o(h,[["render",p]]);export{P as __pageData,f as default};
